-- Generated by ekos-lakehouse (RFC 0195): `rentals` in gold__rentals_by_film_rating_month reconciles to silver.
with mart as (
    select sum("rentals") as v from {{ ref('gold__rentals_by_film_rating_month') }}
),

silver as (
    select count("rental"."rental_id") as v
    from {{ ref('public__rental') }} as "rental"
    left join {{ ref('public__inventory') }} as "inventory"
        on "rental"."inventory_id" = "inventory"."inventory_id"
    left join {{ ref('public__film') }} as "film"
        on "inventory"."film_id" = "film"."film_id"
)

select mart.v as mart_total, silver.v as silver_total
from mart, silver
where mart.v is distinct from silver.v
